mapper.select:
select distinct PROD_ID id, PROD_ABBR text from REP_PROD_INFO where STATUS='E' and p_prod_id is null
and (PROD_ID like concat_ws('%', #{search, jdbcType=VARCHAR}, '%') or PROD_ABBR like concat_ws('%', #{search, jdbcType=VARCHAR}, '%'))
${condition}

select distinct INDENTIFY_MARK id, HOLDER_NAME text from CHB_EQU_HOLD where STATUS='E'
and (INDENTIFY_MARK like concat_ws('%', #{search, jdbcType=VARCHAR}, '%') or HOLDER_NAME like concat_ws('%', #{search, jdbcType=VARCHAR}, '%'))
${condition}
